//! The answers one request returns, and how a response body becomes them.
//!
//! Decoding follows the Python SDK's dispatch path: one pass reads the
//! envelope, then each answer is read on its own. An answer type the API added
//! is skipped with a warning rather than failing the call, an unknown field is
//! ignored, and a field the SDK cannot read is named by a dotted path such as
//! `answers.tone.confidence`.
//!
//! Reading is also where the numbers are held to their contract. A
//! probability is finite and from 0 to 1, a distribution's mass is 1 within
//! [`MASS_TOLERANCE`] per entry, a picked option is one the distribution
//! names, and a score lies within its legend. A door that sends a Noul of
//! `-2.0` is not read as a typed answer; the bytes stay on the raw response.
//! [`SystemOneResponse::check_against`] then holds a response to the request
//! that produced it: every question answered in its own type, and every
//! option and level named the way the question named it.

use std::borrow::Cow;
use std::collections::BTreeMap;

use indexmap::IndexMap;
use reqwest::header::HeaderMap;
use serde::Deserialize;
use serde_json::Value;
use serde_json::value::RawValue;

use crate::Result;
use crate::error::{Error, REQUEST_ID_HEADER, ResponseBody};
use crate::questions::{Entry, Question, Questions};

/// How far from 1 a distribution's mass may fall, per entry.
///
/// The API reports each probability rounded to two decimals, so a
/// distribution of `n` entries may carry `n` half-cents of rounding. A
/// distribution is read when its mass is within `MASS_TOLERANCE × n` of 1,
/// and never tighter than one cent.
pub const MASS_TOLERANCE: f64 = 0.005;

/// The probability that the answer to a Noul question is yes.
#[derive(Debug, Clone, PartialEq, Deserialize)]
pub struct NoulAnswer {
    /// The probability of yes, from 0 to 1.
    pub noul: f64,
    /// The option the estimator's own distribution named, when the door
    /// reports one.
    ///
    /// `noul` is the probability of yes and stays that even when a served
    /// calibration map has pulled it below one half: on a calibrated answer
    /// this field is what `noul` was measured on, so a reader that wants
    /// the estimator's pick reads it rather than deriving one from the
    /// number. When absent, a categorical reader falls back to yes at or
    /// above one half and no below. Absence does not prove that the door is
    /// uncalibrated; legacy responses carry no selected-answer provenance.
    #[serde(default)]
    pub selected: Option<String>,
}

/// The option a Choice question picked, with a probability for each option.
#[derive(Debug, Clone, PartialEq, Deserialize)]
pub struct ChoiceAnswer {
    /// The option the model picked.
    pub choice: String,
    /// How sharp the distribution is, as the API reports it.
    pub confidence: f64,
    /// A probability for each option, in the order the response sends them.
    pub probabilities: IndexMap<String, f64>,
}

/// Where a Score question placed the state, with the rubric it read.
#[derive(Debug, Clone, PartialEq, Deserialize)]
pub struct ScoreAnswer {
    /// The probability-weighted mean level, which falls between levels.
    /// A caller that needs a categorical level reads `selected`, or falls
    /// back to the argmax of `probabilities` when the answer lacks it.
    /// `docs/decision-models/2026-09-20-score-contract.md` states the rule.
    pub score: f64,
    /// How sharp the distribution is, as the API reports it.
    pub confidence: f64,
    /// The level the estimator's own distribution named, when the door
    /// reports one.
    ///
    /// A served calibration map rescales the selected level's probability
    /// without replacing the answer, and can leave a runner-up numerically
    /// larger in `probabilities`; this field is then the only place the
    /// estimator's pick survives the wire. When absent, a categorical reader
    /// falls back to the argmax of `probabilities`, with a tied maximum
    /// resolving to the highest level. Absence is not evidence that no
    /// calibration map was served.
    #[serde(default)]
    pub selected: Option<String>,
    /// The rubric, keyed by level.
    pub legend: BTreeMap<u32, Entry>,
    /// A probability for each level. The API leaves this out on some answers,
    /// and the field is then empty.
    #[serde(default)]
    pub probabilities: BTreeMap<u32, f64>,
}

/// One answer, of whichever type its question asked.
#[derive(Debug, Clone, PartialEq)]
pub enum Answer {
    /// The answer to a Noul question.
    Noul(NoulAnswer),
    /// The answer to a Choice question.
    Choice(ChoiceAnswer),
    /// The answer to a Score question.
    Score(ScoreAnswer),
}

impl Answer {
    /// The wire name of the answer's type.
    #[must_use]
    pub fn kind(&self) -> &'static str {
        match self {
            Self::Noul(_) => "noul",
            Self::Choice(_) => "choice",
            Self::Score(_) => "score",
        }
    }
}

/// What one request cost, as far as the API reports it. The API leaves a count
/// out on some responses.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Deserialize)]
pub struct Usage {
    /// Tokens the state and the questions took.
    #[serde(default)]
    pub input_tokens: Option<u64>,
    /// Tokens the answers took.
    #[serde(default)]
    pub output_tokens: Option<u64>,
}

/// One response as it arrived: its status, its headers, and its bytes.
///
/// The bytes are kept rather than a parsed body, so the order the API sent its
/// answers and its probabilities in survives decoding.
#[derive(Debug, Clone, PartialEq)]
pub struct RawResponse {
    /// The response status.
    pub status: u16,
    /// The response headers.
    pub headers: HeaderMap,
    /// The response body, as it arrived.
    pub bytes: Vec<u8>,
}

impl RawResponse {
    /// The body parsed as JSON when it parses, and as text when it does not.
    /// An empty body is `None`.
    #[must_use]
    pub fn body(&self) -> Option<ResponseBody> {
        crate::transport::parse_body(&self.bytes)
    }

    /// The body as text, with unreadable bytes replaced.
    #[must_use]
    pub fn text(&self) -> Cow<'_, str> {
        String::from_utf8_lossy(&self.bytes)
    }

    /// The request id, when the response carried one.
    #[must_use]
    pub fn request_id(&self) -> Option<&str> {
        self.headers
            .get(REQUEST_ID_HEADER)
            .and_then(|value| value.to_str().ok())
    }
}

/// The answers to one request, with the model that gave them and what they
/// cost.
#[derive(Debug, Clone)]
pub struct SystemOneResponse {
    /// The model the API answered with.
    pub model: String,
    /// Every answer the SDK could read, keyed by question id, in the order the
    /// response sent them.
    pub answers: IndexMap<String, Answer>,
    /// What the request cost.
    pub usage: Usage,
    raw: RawResponse,
}

impl SystemOneResponse {
    /// Read one response body.
    ///
    /// # Errors
    ///
    /// Returns [`Error::ResponseValidation`] naming the first field the SDK
    /// cannot read.
    pub fn decode(raw: RawResponse) -> Result<Self> {
        // Serde reads a struct from a JSON array as well as from an object, and
        // a response is an object, so the first byte is checked here.
        if raw.bytes.iter().find(|byte| !byte.is_ascii_whitespace()) != Some(&b'{') {
            return Err(validation(&raw, "body".to_string()));
        }
        let wire: Wire = serde_json::from_slice(&raw.bytes)
            .map_err(|_| validation(&raw, blame_body(&raw.bytes)))?;
        let model = wire
            .model
            .ok_or_else(|| validation(&raw, "model".to_string()))?;
        let mut answers = IndexMap::with_capacity(wire.answers.len());
        for (id, body) in &wire.answers {
            if let Some(answer) = decode_answer(&raw, id, body)? {
                answers.insert(id.clone(), answer);
            }
        }
        Ok(Self {
            model,
            answers,
            usage: wire.usage.unwrap_or_default(),
            raw,
        })
    }

    /// The response as it arrived.
    #[must_use]
    pub fn raw(&self) -> &RawResponse {
        &self.raw
    }

    /// The request id, when the response carried one. Quote it when you report
    /// a failure to TypeSafe.
    #[must_use]
    pub fn request_id(&self) -> Option<&str> {
        self.raw.request_id()
    }

    /// The Noul answer one question id holds.
    ///
    /// # Errors
    ///
    /// Returns [`Error::MissingAnswer`] when no answer carries that id, and
    /// [`Error::AnswerType`] when the answer is of another type.
    pub fn noul(&self, id: &str) -> Result<&NoulAnswer> {
        match self.answer(id)? {
            Answer::Noul(answer) => Ok(answer),
            other => Err(mismatch(id, "noul", other)),
        }
    }

    /// The Choice answer one question id holds.
    ///
    /// # Errors
    ///
    /// Returns [`Error::MissingAnswer`] when no answer carries that id, and
    /// [`Error::AnswerType`] when the answer is of another type.
    pub fn choice(&self, id: &str) -> Result<&ChoiceAnswer> {
        match self.answer(id)? {
            Answer::Choice(answer) => Ok(answer),
            other => Err(mismatch(id, "choice", other)),
        }
    }

    /// The Score answer one question id holds.
    ///
    /// # Errors
    ///
    /// Returns [`Error::MissingAnswer`] when no answer carries that id, and
    /// [`Error::AnswerType`] when the answer is of another type.
    pub fn score(&self, id: &str) -> Result<&ScoreAnswer> {
        match self.answer(id)? {
            Answer::Score(answer) => Ok(answer),
            other => Err(mismatch(id, "score", other)),
        }
    }

    /// Every Noul answer with its question id, in order.
    pub fn nouls(&self) -> impl Iterator<Item = (&str, &NoulAnswer)> {
        self.answers.iter().filter_map(|(id, answer)| match answer {
            Answer::Noul(answer) => Some((id.as_str(), answer)),
            _ => None,
        })
    }

    /// Every Choice answer with its question id, in order.
    pub fn choices(&self) -> impl Iterator<Item = (&str, &ChoiceAnswer)> {
        self.answers.iter().filter_map(|(id, answer)| match answer {
            Answer::Choice(answer) => Some((id.as_str(), answer)),
            _ => None,
        })
    }

    /// Every Score answer with its question id, in order.
    pub fn scores(&self) -> impl Iterator<Item = (&str, &ScoreAnswer)> {
        self.answers.iter().filter_map(|(id, answer)| match answer {
            Answer::Score(answer) => Some((id.as_str(), answer)),
            _ => None,
        })
    }

    /// Hold the response to the request that produced it.
    ///
    /// Every question must be answered in its own type. A Choice answer
    /// must name exactly the question's options, and a Score answer's
    /// legend and probabilities exactly the question's levels. A
    /// [`Question::Raw`] is held only to being answered, since the SDK does
    /// not read its options.
    ///
    /// # Errors
    ///
    /// Returns [`Error::MissingAnswer`] for a question with no answer,
    /// [`Error::AnswerType`] for one answered in another type, and
    /// [`Error::ResponseValidation`] naming the option or level at fault.
    pub fn check_against(&self, questions: &Questions) -> Result<()> {
        for (id, question) in questions.iter() {
            let answer = self.answer(id)?;
            match (question, answer) {
                (Question::Noul(_), Answer::Noul(_)) | (Question::Raw(_), _) => {}
                (Question::Choice(asked), Answer::Choice(answer)) => {
                    let same = asked.criteria.len() == answer.probabilities.len()
                        && asked
                            .criteria
                            .keys()
                            .all(|option| answer.probabilities.contains_key(option));
                    if !same {
                        let field = answer
                            .probabilities
                            .keys()
                            .find(|option| !asked.criteria.contains_key(*option))
                            .map_or_else(
                                || "probabilities".to_string(),
                                |option| format!("probabilities.{option}"),
                            );
                        return Err(self.mismatch_field(id, &field));
                    }
                }
                (Question::Score(asked), Answer::Score(answer)) => {
                    let levels = asked.criteria.len();
                    if !names_every_level(answer.legend.keys(), levels) {
                        return Err(self.mismatch_field(id, "legend"));
                    }
                    if !answer.probabilities.is_empty()
                        && !names_every_level(answer.probabilities.keys(), levels)
                    {
                        return Err(self.mismatch_field(id, "probabilities"));
                    }
                }
                (Question::Noul(_), found) => return Err(mismatch(id, "noul", found)),
                (Question::Choice(_), found) => return Err(mismatch(id, "choice", found)),
                (Question::Score(_), found) => return Err(mismatch(id, "score", found)),
            }
        }
        Ok(())
    }

    /// The validation error for an answer field that does not match the
    /// question.
    fn mismatch_field(&self, id: &str, field: &str) -> Error {
        validation(&self.raw, format!("answers.{id}.{field}"))
    }

    /// One answer of any type.
    fn answer(&self, id: &str) -> Result<&Answer> {
        self.answers
            .get(id)
            .ok_or_else(|| Error::MissingAnswer { id: id.to_string() })
    }
}

/// The response body, with each answer left as bytes so an unknown type is
/// skipped one answer at a time.
#[derive(Deserialize)]
struct Wire {
    #[serde(default)]
    model: Option<String>,
    #[serde(default)]
    usage: Option<Usage>,
    #[serde(default)]
    answers: IndexMap<String, Box<RawValue>>,
}

/// An answer's type, read before the answer itself.
#[derive(Deserialize)]
struct Tag {
    #[serde(default)]
    r#type: Option<String>,
}

/// One answer, or `None` when its type is one this crate does not model.
fn decode_answer(raw: &RawResponse, id: &str, body: &RawValue) -> Result<Option<Answer>> {
    let tag: Tag = serde_json::from_str(body.get())
        .map_err(|_| validation(raw, format!("answers.{id}.type")))?;
    let kind = tag
        .r#type
        .ok_or_else(|| validation(raw, format!("answers.{id}.type")))?;
    match kind.as_str() {
        "noul" => {
            let answer: NoulAnswer = read(raw, id, body, NOUL_FIELDS)?;
            if let Some(field) = noul_fault(&answer) {
                return Err(validation(raw, format!("answers.{id}.{field}")));
            }
            Ok(Some(Answer::Noul(answer)))
        }
        "choice" => {
            let answer: ChoiceAnswer = read(raw, id, body, CHOICE_FIELDS)?;
            if let Some(field) = choice_fault(&answer) {
                return Err(validation(raw, format!("answers.{id}.{field}")));
            }
            Ok(Some(Answer::Choice(answer)))
        }
        "score" => {
            let answer: ScoreAnswer = read(raw, id, body, SCORE_FIELDS)?;
            if let Some(field) = score_fault(&answer) {
                return Err(validation(raw, format!("answers.{id}.{field}")));
            }
            Ok(Some(Answer::Score(answer)))
        }
        other => {
            // A newer API may answer with a type this crate does not model. The
            // rest of the response still reads, and the bytes stay on `raw()`.
            tracing::warn!(
                target: "jev",
                answer = id,
                answer_type = other,
                "skipping an answer of a type this client does not read"
            );
            Ok(None)
        }
    }
}

/// Whether a level map's keys are exactly `0..levels`: as many keys as
/// levels, each below the count, with no repeats possible in a map.
fn names_every_level<'a>(keys: impl ExactSizeIterator<Item = &'a u32>, levels: usize) -> bool {
    keys.len() == levels && keys.into_iter().all(|level| (*level as usize) < levels)
}

/// Whether a number is a probability: finite, from 0 to 1.
fn is_probability(value: f64) -> bool {
    value.is_finite() && (0.0..=1.0).contains(&value)
}

/// The first entry of a distribution that is not a probability, or
/// `probabilities` itself when the entries do not sum to 1 within tolerance.
/// An empty distribution is not checked; the API leaves one out on some
/// Score answers.
fn mass_fault<'a, K: std::fmt::Display>(
    probabilities: impl ExactSizeIterator<Item = (K, &'a f64)>,
) -> Option<String> {
    let entries = probabilities.len();
    if entries == 0 {
        return None;
    }
    let mut mass = 0.0;
    for (key, value) in probabilities {
        if !is_probability(*value) {
            return Some(format!("probabilities.{key}"));
        }
        mass += value;
    }
    let allowed = (MASS_TOLERANCE * entries as f64).max(0.01);
    ((mass - 1.0).abs() > allowed).then(|| "probabilities".to_string())
}

/// The field of a Noul answer that breaks the contract, if one does.
fn noul_fault(answer: &NoulAnswer) -> Option<&'static str> {
    if !is_probability(answer.noul) {
        return Some("noul");
    }
    if answer
        .selected
        .as_deref()
        .is_some_and(|option| !matches!(option, "no" | "yes"))
    {
        return Some("selected");
    }
    None
}

/// The field of a Choice answer that breaks the contract, if one does: a
/// confidence or probability out of range, a mass away from 1, an empty
/// distribution, or a choice the distribution does not name.
fn choice_fault(answer: &ChoiceAnswer) -> Option<String> {
    if !is_probability(answer.confidence) {
        return Some("confidence".to_string());
    }
    if answer.probabilities.is_empty() {
        return Some("probabilities".to_string());
    }
    if let Some(field) = mass_fault(answer.probabilities.iter()) {
        return Some(field);
    }
    if !answer.probabilities.contains_key(&answer.choice) {
        return Some("choice".to_string());
    }
    None
}

/// The field of a Score answer that breaks the contract, if one does: an
/// empty legend, a confidence or probability out of range, a mass away
/// from 1, a probability for a level the legend lacks, a score outside the
/// legend's levels, or a selected level the distribution does not name.
fn score_fault(answer: &ScoreAnswer) -> Option<String> {
    let (Some(lowest), Some(highest)) = (
        answer.legend.keys().next(),
        answer.legend.keys().next_back(),
    ) else {
        return Some("legend".to_string());
    };
    if !is_probability(answer.confidence) {
        return Some("confidence".to_string());
    }
    if !answer.score.is_finite()
        || answer.score < f64::from(*lowest)
        || answer.score > f64::from(*highest)
    {
        return Some("score".to_string());
    }
    if let Some(level) = answer
        .probabilities
        .keys()
        .find(|level| !answer.legend.contains_key(level))
    {
        return Some(format!("probabilities.{level}"));
    }
    if let Some(field) = mass_fault(answer.probabilities.iter()) {
        return Some(field);
    }
    if let Some(selected) = &answer.selected {
        let valid = selected.parse::<u32>().ok().is_some_and(|level| {
            level.to_string() == *selected && answer.probabilities.contains_key(&level)
        });
        if !valid {
            return Some("selected".to_string());
        }
    }
    None
}

/// One answer of a known type, or the first field that stopped it.
fn read<T: for<'de> Deserialize<'de>>(
    raw: &RawResponse,
    id: &str,
    body: &RawValue,
    fields: &[Field],
) -> Result<T> {
    serde_json::from_str(body.get()).map_err(|_| {
        let path = match blame_field(body.get(), fields) {
            Some(field) => format!("answers.{id}.{field}"),
            None => format!("answers.{id}"),
        };
        validation(raw, path)
    })
}

/// One field of an answer: its name, the JSON shape it takes, and whether the
/// API may leave it out.
struct Field {
    name: &'static str,
    shape: Shape,
    required: bool,
}

/// The JSON shape a field takes on the wire.
enum Shape {
    Number,
    Text,
    Object,
}

const NOUL_FIELDS: &[Field] = &[
    Field {
        name: "noul",
        shape: Shape::Number,
        required: true,
    },
    Field {
        name: "selected",
        shape: Shape::Text,
        required: false,
    },
];

const CHOICE_FIELDS: &[Field] = &[
    Field {
        name: "choice",
        shape: Shape::Text,
        required: true,
    },
    Field {
        name: "confidence",
        shape: Shape::Number,
        required: true,
    },
    Field {
        name: "probabilities",
        shape: Shape::Object,
        required: true,
    },
];

const SCORE_FIELDS: &[Field] = &[
    Field {
        name: "score",
        shape: Shape::Number,
        required: true,
    },
    Field {
        name: "confidence",
        shape: Shape::Number,
        required: true,
    },
    Field {
        name: "legend",
        shape: Shape::Object,
        required: true,
    },
    Field {
        name: "selected",
        shape: Shape::Text,
        required: false,
    },
    Field {
        name: "probabilities",
        shape: Shape::Object,
        required: false,
    },
];

/// The first field that is missing or the wrong shape, for the dotted path an
/// error names.
fn blame_field(body: &str, fields: &[Field]) -> Option<String> {
    let value: Value = serde_json::from_str(body).ok()?;
    for field in fields {
        match value.get(field.name) {
            None => {
                if field.required {
                    return Some(field.name.to_string());
                }
            }
            Some(found) => {
                let fits = match field.shape {
                    Shape::Number => found.is_number(),
                    Shape::Text => found.is_string(),
                    Shape::Object => found.is_object(),
                };
                if !fits {
                    return Some(field.name.to_string());
                }
                // A level map decodes only when every key is a level, and a
                // probability map only when every value is a number. The path
                // names the entry at fault, the way the Python SDK does.
                if matches!(field.name, "legend" | "probabilities")
                    && let Some(bad) = blame_entry(field.name, found)
                {
                    return Some(bad);
                }
            }
        }
    }
    None
}

/// The entry of a level map that does not decode: a key that is not a level
/// number, or for `probabilities` a value that is not a number.
fn blame_entry(field: &str, map: &Value) -> Option<String> {
    for (key, value) in map.as_object()? {
        if key.parse::<u32>().is_err() || (field == "probabilities" && !value.is_number()) {
            return Some(format!("{field}.{key}"));
        }
    }
    None
}

/// Which top-level field stopped the body from reading at all.
fn blame_body(bytes: &[u8]) -> String {
    let Ok(value) = serde_json::from_slice::<Value>(bytes) else {
        return "body".to_string();
    };
    let Some(object) = value.as_object() else {
        return "body".to_string();
    };
    if object.get("model").is_some_and(|model| !model.is_string()) {
        return "model".to_string();
    }
    match object.get("answers") {
        Some(answers) if !answers.is_object() => "answers".to_string(),
        _ => match object.get("usage") {
            Some(usage) if !usage.is_object() && !usage.is_null() => "usage".to_string(),
            _ => "body".to_string(),
        },
    }
}

/// The error a body the SDK cannot read raises.
fn validation(raw: &RawResponse, field_path: String) -> Error {
    Error::ResponseValidation {
        status: raw.status,
        field_path,
        body: raw.body().map(Box::new),
        request_id: raw.request_id().map(str::to_string),
    }
}

/// The error a typed accessor raises when the id holds another type.
fn mismatch(id: &str, expected: &'static str, found: &Answer) -> Error {
    Error::AnswerType {
        id: id.to_string(),
        expected,
        found: found.kind(),
    }
}

//! The client, the request it sends, and the loop that retries one.
//!
//! One attempt is one HTTP round trip under one timeout. A failure the policy
//! retries waits and runs again, and the wait is the policy's own unless the
//! server asked for a longer one. Every attempt and every retry is one `info`
//! line under the `jev` target.

use std::sync::Arc;
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::{Duration, Instant};

use reqwest::header::{HeaderMap, HeaderValue};
use reqwest::{Method, StatusCode};
use serde_json::{Map, Value};

use crate::Result;
use crate::answers::{RawResponse, SystemOneResponse};
use crate::config::{ApiKey, Config};
use crate::error::{ApiError, Error, REQUEST_ID_HEADER};
use crate::models::{ListOptions, Models};
use crate::questions::{Entry, Questions};
use crate::retry::{RETRY_COUNT_HEADER, RetryPolicy};
use crate::transport;

/// The route that answers questions.
const SYSTEM_ONE_PATH: &str = "/v1/systemone";

/// The route that lists models.
const MODELS_PATH: &str = "/v1/models";

/// One state, the questions to ask about it, and what this call overrides.
///
/// ```
/// use jev::{Noul, Questions, SystemOneRequest};
///
/// let request = SystemOneRequest::new(
///     "I was charged twice for one order.",
///     Questions::new().with("billing", Noul::new("Is this about a charge?")),
/// )
/// .model("jev-latest");
/// ```
#[derive(Debug, Clone)]
pub struct SystemOneRequest {
    /// The state every question reads. One state, not a batch.
    pub state: Entry,
    /// The questions to ask.
    pub questions: Questions,
    /// The model to ask, or the client's default.
    pub model: Option<String>,
    /// The policy to retry this call by, or the client's own.
    pub retry: Option<RetryPolicy>,
    /// The timeout each attempt of this call takes, or the client's own.
    pub timeout: Option<Duration>,
    /// Headers this call adds.
    pub headers: HeaderMap,
    /// Fields to merge into the body last, for a field the API takes and this
    /// crate does not model. A field here replaces one the SDK wrote.
    pub extra_body: Map<String, Value>,
}

impl SystemOneRequest {
    /// Ask questions about one state.
    #[must_use]
    pub fn new<E: Into<Entry>>(state: E, questions: Questions) -> Self {
        Self {
            state: state.into(),
            questions,
            model: None,
            retry: None,
            timeout: None,
            headers: HeaderMap::new(),
            extra_body: Map::new(),
        }
    }

    /// Ask another model than the client's default.
    #[must_use]
    pub fn model<M: Into<String>>(mut self, model: M) -> Self {
        self.model = Some(model.into());
        self
    }

    /// Retry this call by another policy.
    ///
    /// The policy replaces the client's. Build one over the client's own with
    /// struct update syntax when you mean to change one field:
    /// `RetryPolicy { max_retries: 0, ..client.retry().clone() }`.
    #[must_use]
    pub fn retry(mut self, retry: RetryPolicy) -> Self {
        self.retry = Some(retry);
        self
    }

    /// Give each attempt of this call another timeout.
    #[must_use]
    pub fn timeout(mut self, timeout: Duration) -> Self {
        self.timeout = Some(timeout);
        self
    }

    /// Add headers to this call.
    #[must_use]
    pub fn headers(mut self, headers: HeaderMap) -> Self {
        self.headers = headers;
        self
    }

    /// Merge fields into the body last.
    #[must_use]
    pub fn extra_body(mut self, extra: Map<String, Value>) -> Self {
        self.extra_body = extra;
        self
    }

    /// The body one call of this request sends, with `default_model` where
    /// the request names no model of its own. Nothing goes out: a caller
    /// that records the exchange reads it.
    ///
    /// # Errors
    ///
    /// Returns [`Error::Question`] when the question set fails its checks and
    /// [`Error::Config`] when the questions do not serialize.
    pub fn body(&self, default_model: &str) -> Result<Map<String, Value>> {
        self.questions.validate()?;
        let mut body = Map::new();
        body.insert("state".to_string(), self.state.to_value());
        body.insert(
            "model".to_string(),
            Value::String(
                self.model
                    .clone()
                    .unwrap_or_else(|| default_model.to_string()),
            ),
        );
        body.insert(
            "questions".to_string(),
            serde_json::to_value(&self.questions)
                .map_err(|error| Error::Config(format!("the questions are not JSON: {error}")))?,
        );
        for (name, value) in &self.extra_body {
            body.insert(name.clone(), value.clone());
        }
        Ok(body)
    }
}

/// A client for TypeSafe's System One API.
///
/// The client is cheap to clone and holds one HTTP connection pool, so build
/// one and share it.
#[derive(Debug, Clone)]
pub struct Client {
    inner: Arc<Inner>,
}

/// What every request reads, behind one allocation.
#[derive(Debug)]
struct Inner {
    api_key: ApiKey,
    base_url: String,
    default_model: String,
    timeout: Duration,
    retry: RetryPolicy,
    default_headers: HeaderMap,
    http: reqwest::Client,
    requests: AtomicU64,
}

impl Client {
    /// Build a client from settings, filling in what they leave out from the
    /// environment and the defaults.
    ///
    /// # Errors
    ///
    /// Returns [`Error::Config`] when no key is set, the base URL is not an
    /// http or https URL, the timeout is zero, or a retry field is out of
    /// range.
    pub fn new(config: Config) -> Result<Self> {
        let resolved = config.resolve()?;
        Ok(Self {
            inner: Arc::new(Inner {
                api_key: resolved.api_key,
                base_url: resolved.base_url,
                default_model: resolved.default_model,
                timeout: resolved.timeout,
                retry: resolved.retry,
                default_headers: resolved.default_headers,
                http: resolved.http,
                requests: AtomicU64::new(0),
            }),
        })
    }

    /// Build a client from the environment and the defaults alone.
    ///
    /// # Errors
    ///
    /// Returns the same errors as [`Client::new`].
    pub fn from_env() -> Result<Self> {
        Self::new(Config::new())
    }

    /// The API root, with trailing slashes dropped.
    #[must_use]
    pub fn base_url(&self) -> &str {
        &self.inner.base_url
    }

    /// The model a request that names none asks.
    #[must_use]
    pub fn default_model(&self) -> &str {
        &self.inner.default_model
    }

    /// How long one attempt may take.
    #[must_use]
    pub fn timeout(&self) -> Duration {
        self.inner.timeout
    }

    /// What the client retries and how long it waits.
    #[must_use]
    pub fn retry(&self) -> &RetryPolicy {
        &self.inner.retry
    }

    /// The headers every request carries, before the ones the API reads to
    /// identify it.
    #[must_use]
    pub fn default_headers(&self) -> &HeaderMap {
        &self.inner.default_headers
    }

    /// The models the account can ask.
    #[must_use]
    pub fn models(&self) -> Models<'_> {
        Models::new(self)
    }

    /// Ask questions about one state and read the answers.
    ///
    /// The policy's `budget`, when set, is a monotonic deadline for the whole
    /// call, including the first attempt, the body read, every wait, and
    /// every retry; each attempt's timeout is capped at the time the call has
    /// left.
    ///
    /// # Errors
    ///
    /// Returns [`Error::Question`] when the question set fails its checks,
    /// before any request. Returns [`Error::Api`], [`Error::Connection`], or
    /// [`Error::Timeout`] when the call fails after its retries or runs out
    /// of budget, and [`Error::ResponseValidation`] when the answers do not
    /// read or do not hold to their numeric contract. Returns
    /// [`Error::MissingAnswer`] or [`Error::AnswerType`] when a question
    /// went unanswered or was answered in another type; a Choice or Score
    /// answered over other options than the question named is
    /// [`Error::ResponseValidation`]. A caller that wants the bytes
    /// regardless reads [`Client::system_one_raw`].
    pub async fn system_one(&self, request: SystemOneRequest) -> Result<SystemOneResponse> {
        let prepared = self.prepare_system_one(&request)?;
        let raw = self.send_read(&prepared).await?;
        let response = SystemOneResponse::decode(raw)?;
        Ok(response)
    }

    /// Ask questions about one state and hand back the response unread, for a
    /// caller that wants the bytes.
    ///
    /// The call is bounded the way [`Client::system_one`] is, and the
    /// returned response's body stays under the same deadline: the attempt's
    /// timeout — capped by the remaining budget — still applies while the
    /// caller reads the body, so a read past the deadline fails rather than
    /// outliving the call's budget.
    ///
    /// # Errors
    ///
    /// Returns the same errors as [`Client::system_one`], other than
    /// [`Error::ResponseValidation`].
    pub async fn system_one_raw(&self, request: SystemOneRequest) -> Result<reqwest::Response> {
        let prepared = self.prepare_system_one(&request)?;
        self.send(&prepared).await
    }

    /// Everything one `POST /v1/systemone` call sends, before its first
    /// attempt.
    fn prepare_system_one(&self, request: &SystemOneRequest) -> Result<Prepared> {
        let body = request.body(&self.inner.default_model)?;
        let encoded = serde_json::to_vec(&Value::Object(body))
            .map_err(|error| Error::Config(format!("the request body is not JSON: {error}")))?;
        self.prepare(
            Method::POST,
            SYSTEM_ONE_PATH,
            Some(encoded),
            &request.headers,
            request.timeout,
            request.retry.clone(),
        )
    }

    /// One `GET /v1/models`, read into bytes.
    pub(crate) async fn list_models(&self, options: ListOptions) -> Result<RawResponse> {
        let prepared = self.prepare(
            Method::GET,
            MODELS_PATH,
            None,
            &options.headers,
            options.timeout,
            options.retry,
        )?;
        self.send_read(&prepared).await
    }

    /// Everything one call sends, before its first attempt.
    fn prepare(
        &self,
        method: Method,
        path: &'static str,
        body: Option<Vec<u8>>,
        headers: &HeaderMap,
        timeout: Option<Duration>,
        retry: Option<RetryPolicy>,
    ) -> Result<Prepared> {
        let timeout = timeout.unwrap_or(self.inner.timeout);
        if timeout.is_zero() {
            return Err(Error::Config(
                "`timeout` must be a positive duration".to_string(),
            ));
        }
        let retry = match retry {
            Some(retry) => {
                retry.validate()?;
                retry
            }
            None => self.inner.retry.clone(),
        };
        let headers = transport::headers(
            &self.inner.default_headers,
            headers,
            &self.inner.api_key,
            body.is_some(),
        )?;
        Ok(Prepared {
            tag: self.inner.requests.fetch_add(1, Ordering::Relaxed) + 1,
            url: format!("{}{path}", self.inner.base_url),
            endpoint: format!("{method} {}{path}", endpoint_of(&self.inner.base_url)),
            method,
            body,
            headers,
            timeout,
            retry,
        })
    }

    /// One call: the first attempt and every retry the policy allows.
    async fn send(&self, prepared: &Prepared) -> Result<reqwest::Response> {
        self.send_with(prepared, Client::attempt).await
    }

    /// One call whose body is read inside each attempt, so a body that stalls
    /// or breaks is retried the way both official SDKs retry one.
    async fn send_read(&self, prepared: &Prepared) -> Result<RawResponse> {
        self.send_with(prepared, Client::attempt_read).await
    }

    /// The retry loop both send paths share.
    ///
    /// `retry.budget`, when set, is a monotonic deadline for the whole call,
    /// measured from the first attempt's dispatch: it covers the first
    /// attempt, every retry, every wait between them, and the body a read
    /// path consumes inside its attempt. Each attempt's timeout is the
    /// smaller of the call's own timeout and the time the call has left, so
    /// a reply that arrives after the deadline cannot succeed, and a retry
    /// whose wait would reach the deadline never runs.
    async fn send_with<T>(
        &self,
        prepared: &Prepared,
        attempt: impl AsyncFn(&Client, &Prepared, u32, Duration) -> std::result::Result<T, Failed>,
    ) -> Result<T> {
        let started = Instant::now();
        // A budget too large to name on this clock is no deadline at all.
        let deadline = prepared
            .retry
            .budget
            .and_then(|budget| started.checked_add(budget));
        let mut attempt_no: u32 = 0;
        let mut last: Option<Failed> = None;
        loop {
            let timeout = match deadline {
                Some(deadline) => {
                    let remaining = deadline.saturating_duration_since(Instant::now());
                    if remaining.is_zero() {
                        // The call's time is spent. The failure already held
                        // is the answer; a call that never ran an attempt
                        // reports the bound it ran out of.
                        return Err(match last {
                            Some(failed) => failed.error,
                            None => Error::Timeout {
                                timeout: prepared
                                    .retry
                                    .budget
                                    .map_or(prepared.timeout, |b| prepared.timeout.min(b)),
                            },
                        });
                    }
                    prepared.timeout.min(remaining)
                }
                None => prepared.timeout,
            };
            match attempt(self, prepared, attempt_no, timeout).await {
                Ok(done) => return Ok(done),
                Err(failed) => {
                    let retries_left = prepared.retry.max_retries.saturating_sub(attempt_no);
                    if retries_left == 0 || !prepared.retry.retries_error(&failed.error) {
                        return Err(failed.error);
                    }
                    let delay = prepared.retry.delay(attempt_no, failed.headers.as_ref());
                    if let Some(budget) = prepared.retry.budget
                        && started.elapsed().saturating_add(delay) >= budget
                    {
                        tracing::info!(
                            target: "jev",
                            request = prepared.tag,
                            budget_ms = budget.as_millis(),
                            "the retry budget is spent; returning the last failure"
                        );
                        return Err(failed.error);
                    }
                    tracing::info!(
                        target: "jev",
                        request = prepared.tag,
                        retry = attempt_no + 1,
                        of = prepared.retry.max_retries,
                        delay_ms = delay.as_millis(),
                        reason = %failed.error,
                        "waiting before the next attempt"
                    );
                    tokio::time::sleep(delay).await;
                    attempt_no += 1;
                    last = Some(failed);
                }
            }
        }
    }

    /// One HTTP round trip under one timeout, with the body read inside the
    /// timeout as well. A body that breaks is a connection failure the policy
    /// can retry.
    async fn attempt_read(
        &self,
        prepared: &Prepared,
        attempt: u32,
        timeout: Duration,
    ) -> std::result::Result<RawResponse, Failed> {
        let response = self.attempt(prepared, attempt, timeout).await?;
        let status = response.status().as_u16();
        let headers = response.headers().clone();
        match response.bytes().await {
            Ok(bytes) => Ok(RawResponse {
                status,
                headers,
                bytes: bytes.to_vec(),
            }),
            Err(source) => {
                // A body that stalls past the timeout is a timeout, the way
                // the Python SDK names a read timeout.
                let error = if source.is_timeout() {
                    Error::Timeout { timeout }
                } else {
                    Error::connection(source)
                };
                Err(Failed {
                    error,
                    headers: Some(headers),
                })
            }
        }
    }

    /// One HTTP round trip under one timeout: the smaller of the call's own
    /// and the time a budget leaves it. The reqwest timeout holds through the
    /// body read, so a body that stalls past the deadline ends the attempt
    /// the same way a stalled head does.
    async fn attempt(
        &self,
        prepared: &Prepared,
        attempt: u32,
        timeout: Duration,
    ) -> std::result::Result<reqwest::Response, Failed> {
        let mut headers = prepared.headers.clone();
        if attempt > 0 {
            headers.insert(RETRY_COUNT_HEADER, HeaderValue::from(attempt));
        }
        tracing::debug!(
            target: "jev",
            request = prepared.tag,
            method = %prepared.method,
            url = %prepared.url,
            headers = %transport::redact(&headers),
            body = %prepared.body_text(),
            "sending an attempt"
        );
        let mut builder = self
            .inner
            .http
            .request(prepared.method.clone(), &prepared.url)
            .headers(headers)
            .timeout(timeout);
        if let Some(body) = prepared.body.clone() {
            builder = builder.body(body);
        }
        let began = Instant::now();
        let response = match builder.send().await {
            Ok(response) => response,
            Err(error) => {
                let timed_out = error.is_timeout();
                let failure = if timed_out {
                    Error::Timeout { timeout }
                } else {
                    Error::connection(error)
                };
                tracing::info!(
                    target: "jev",
                    request = prepared.tag,
                    method = %prepared.method,
                    url = %prepared.url,
                    elapsed_ms = began.elapsed().as_millis(),
                    reason = %failure,
                    "the attempt did not reach the API"
                );
                return Err(Failed {
                    error: failure,
                    headers: None,
                });
            }
        };
        let status = response.status();
        tracing::info!(
            target: "jev",
            request = prepared.tag,
            method = %prepared.method,
            url = %prepared.url,
            status = status.as_u16(),
            elapsed_ms = began.elapsed().as_millis(),
            request_id = request_id(response.headers()).unwrap_or("-"),
            "the API answered"
        );
        if status.is_success() {
            return Ok(response);
        }
        Err(self.failure(prepared, status, response).await)
    }

    /// The error one failed response raises, with its body read.
    async fn failure(
        &self,
        prepared: &Prepared,
        status: StatusCode,
        response: reqwest::Response,
    ) -> Failed {
        let headers = response.headers().clone();
        let bytes = response
            .bytes()
            .await
            .map(|bytes| bytes.to_vec())
            .unwrap_or_default();
        let body = transport::parse_body(&bytes);
        tracing::debug!(
            target: "jev",
            request = prepared.tag,
            status = status.as_u16(),
            headers = %transport::redact(&headers),
            body = %String::from_utf8_lossy(&bytes),
            "the failed response carried this body"
        );
        Failed {
            error: Error::from(ApiError::new(
                prepared.endpoint.clone(),
                status.as_u16(),
                headers.clone(),
                body,
            )),
            headers: Some(headers),
        }
    }
}

/// One attempt that failed, with the response headers when there was a
/// response, so the retry can honor a server delay.
struct Failed {
    error: Error,
    headers: Option<HeaderMap>,
}

/// Everything one call sends, reused by every attempt.
struct Prepared {
    tag: u64,
    method: Method,
    url: String,
    endpoint: String,
    body: Option<Vec<u8>>,
    headers: HeaderMap,
    timeout: Duration,
    retry: RetryPolicy,
}

impl Prepared {
    /// The body as text for a `debug` line. Bodies are logged as they are sent,
    /// the way both official SDKs log them.
    fn body_text(&self) -> String {
        match self.body.as_deref() {
            Some(bytes) => String::from_utf8_lossy(bytes).into_owned(),
            None => String::new(),
        }
    }
}

impl RawResponse {
    /// Read one response into its status, its headers, and its bytes.
    ///
    /// # Errors
    ///
    /// Returns [`Error::Connection`] when the body does not arrive.
    pub async fn read(response: reqwest::Response) -> Result<Self> {
        let status = response.status().as_u16();
        let headers = response.headers().clone();
        let bytes = response.bytes().await.map_err(Error::connection)?.to_vec();
        Ok(Self {
            status,
            headers,
            bytes,
        })
    }
}

/// The base URL as an error's endpoint names it: the credentials, the query,
/// and the fragment dropped, the way the Python SDK writes a request's URL.
fn endpoint_of(base_url: &str) -> String {
    let mut parsed = match url::Url::parse(base_url) {
        Ok(parsed) => parsed,
        Err(_) => return base_url.to_string(),
    };
    let _ = parsed.set_username("");
    let _ = parsed.set_password(None);
    parsed.set_query(None);
    parsed.set_fragment(None);
    parsed.to_string().trim_end_matches('/').to_string()
}

/// The request id one response carries.
fn request_id(headers: &HeaderMap) -> Option<&str> {
    headers
        .get(REQUEST_ID_HEADER)
        .and_then(|value| value.to_str().ok())
}

/// A client for a caller that runs no `tokio` runtime of its own.
///
/// Each call runs on a runtime this client owns. Do not call it from inside a
/// runtime; use [`Client`] there.
#[cfg(feature = "blocking")]
#[derive(Debug)]
pub struct BlockingClient {
    client: Client,
    runtime: tokio::runtime::Runtime,
}

#[cfg(feature = "blocking")]
impl BlockingClient {
    /// Build a blocking client from settings.
    ///
    /// # Errors
    ///
    /// Returns the same errors as [`Client::new`], and [`Error::Config`] when
    /// the runtime does not start.
    pub fn new(config: Config) -> Result<Self> {
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .map_err(|error| Error::Config(format!("the runtime did not start: {error}")))?;
        Ok(Self {
            client: Client::new(config)?,
            runtime,
        })
    }

    /// Build a blocking client from the environment and the defaults alone.
    ///
    /// # Errors
    ///
    /// Returns the same errors as [`BlockingClient::new`].
    pub fn from_env() -> Result<Self> {
        Self::new(Config::new())
    }

    /// The async client underneath.
    #[must_use]
    pub fn client(&self) -> &Client {
        &self.client
    }

    /// Ask questions about one state and read the answers.
    ///
    /// # Errors
    ///
    /// Returns the same errors as [`Client::system_one`].
    pub fn system_one(&self, request: SystemOneRequest) -> Result<SystemOneResponse> {
        self.runtime.block_on(self.client.system_one(request))
    }

    /// List the models the account can ask.
    ///
    /// # Errors
    ///
    /// Returns the same errors as [`crate::Models::list`].
    pub fn list_models(&self, options: ListOptions) -> Result<Vec<crate::ModelCard>> {
        self.runtime.block_on(self.client.models().list(options))
    }
}

